const response = $input.first()?.json || {};
const data = response.data || response;

// Si el backend indica que para hoy no toca reporte, frena la ejecución
if (response.despachar === false || data.despachar === false) {
  return [];
}

// Destinatarios y período definidos por el backend
const destinatarios = data.destinatarios || response.destinatarios || ["admin@akros.lat", "gerencia@akros.lat"];
const periodoRaw = (data.periodo || response.periodo || "weekly").toLowerCase();

const mapaPeriodos = {
  daily: "Diario",
  weekly: "Semanal",
  monthly: "Mensual",
  yearly: "Anual"
};
const periodoTexto = mapaPeriodos[periodoRaw] || "Periódico";

// Extracción de métricas de TSK-BE-24
const kpis = data.kpisConsolidados || {
  recaudacionTotal: data.recaudacionTotal ?? data.totalRecaudacion ?? 0,
  afluenciaTotal: data.afluenciaTotal ?? data.totalAfluencia ?? 0,
  reservasTotales: data.reservasTotales ?? data.totalReservas ?? 0,
  cuposVendidos: data.cuposVendidos ?? data.totalCupos ?? 0
};

// Formato moneda legal colombiana
const formatCOP = (val) => new Intl.NumberFormat('es-CO', { 
  style: 'currency', 
  currency: 'COP', 
  maximumFractionDigits: 0 
}).format(val || 0);

// Plantilla Dark Theme AKROS Club
const htmlReport = `
<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background-color: #0b0f0d; margin: 0; padding: 32px 16px; color: #f1f5f9; }
    .container { max-width: 600px; margin: 0 auto; background: #111815; border: 1px solid #1f2c25; border-radius: 16px; padding: 32px; box-shadow: 0 12px 30px rgba(0,0,0,0.4); }
    .badge { display: inline-block; background: rgba(201, 239, 117, 0.12); color: #c9ef75; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; padding: 6px 14px; border-radius: 9999px; margin-bottom: 12px; }
    h1 { font-size: 22px; margin: 0 0 6px 0; color: #ffffff; }
    p.subtitle { color: #8da499; font-size: 13px; margin: 0 0 28px 0; }
    .kpi-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 28px; }
    .kpi-card { background: #16221d; border: 1px solid #23342c; border-radius: 12px; padding: 18px; }
    .kpi-label { font-size: 12px; color: #7d968b; margin-bottom: 6px; text-transform: uppercase; letter-spacing: 0.5px; }
    .kpi-value { font-size: 20px; font-weight: 700; color: #c9ef75; font-family: ui-monospace, monospace; }
    .footer { font-size: 12px; color: #556b61; text-align: center; border-top: 1px solid #1f2c25; padding-top: 20px; margin-top: 24px; line-height: 1.5; }
  </style>
</head>
<body>
  <div class="container">
    <div style="text-align: center;">
      <div class="badge">Reporte Gerencial &bull; ${periodoTexto}</div>
      <h1>AKROS Club &bull; Métricas Clave</h1>
      <p class="subtitle">Consolidado automático &bull; Hora legal Colombia (UTC-5)</p>
    </div>

    <div class="kpi-grid">
      <div class="kpi-card">
        <div class="kpi-label">Recaudación Total</div>
        <div class="kpi-value">${formatCOP(kpis.recaudacionTotal)}</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Afluencia (Tickets Usados)</div>
        <div class="kpi-value">${kpis.afluenciaTotal}</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Total Reservas</div>
        <div class="kpi-value">${kpis.reservasTotales}</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Cupos Vendidos</div>
        <div class="kpi-value">${kpis.cuposVendidos}</div>
      </div>
    </div>

    <div class="footer">
      Mensaje emitido automáticamente por la infraestructura n8n de AKROS Club.<br>
      Corte analítico generado el ${new Date().toLocaleDateString('es-CO', { timeZone: 'America/Bogota' })}.
    </div>
  </div>
</body>
</html>
`;

return [
  {
    json: {
      from: "Akros Gerencia <no-reply@akros.lat>",
      to: Array.isArray(destinatarios) ? destinatarios : [destinatarios],
      subject: `📊 Reporte Gerencial ${periodoTexto} - AKROS Club`,
      html: htmlReport
    }
  }
];
